CREATE TABLE t_identity_always (id INT GENERATED ALWAYS AS IDENTITY);

CREATE TABLE t_identity_by_default (id INT GENERATED BY DEFAULT AS IDENTITY);

CREATE TABLE t_identity_options (
    id BIGINT GENERATED ALWAYS AS IDENTITY (
        START WITH 10
        INCREMENT BY 2
        MINVALUE 1
        MAXVALUE 1000
        NO CYCLE
        CACHE 20
        ORDER
    )
);

CREATE TABLE t_identity_no_options (
    id INT GENERATED BY DEFAULT AS IDENTITY (NO MINVALUE NO MAXVALUE NO CACHE NO ORDER)
);

CREATE TABLE t_identity_cycle (
    id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 CYCLE)
);

CREATE TABLE t_identity_compound_no_options (
    id INT GENERATED ALWAYS AS IDENTITY (NOMINVALUE NOMAXVALUE NOCYCLE NOCACHE NOORDER)
);

CREATE TABLE t_identity_signed_range (
    id INT GENERATED ALWAYS AS IDENTITY (MINVALUE -2147483648 MAXVALUE 2147483647)
);

CREATE TABLE t_generated_column (
    a INT,
    b INT GENERATED ALWAYS AS (a + 1)
);

CREATE TABLE t_generated_column_expression (
    a VARCHAR(20),
    b VARCHAR(21) GENERATED ALWAYS AS (a || 'x')
);

CREATE TABLE t_identity_and_generated (
    id INT GENERATED ALWAYS AS IDENTITY,
    doubled INT GENERATED ALWAYS AS (id * 2) NOT NULL
);
